import{_ as a,o as e,c as r,a5 as d}from"./chunks/framework.BF53ZjCA.js";const g=JSON.parse('{"title":"同色宝石判别","description":"","frontmatter":{"title":"同色宝石判别","identification":"same-color-gems"},"headers":[],"relativePath":"zh/identification/same-color-gems.md","filePath":"zh/identification/same-color-gems.md","lastUpdated":1790876393000}'),l={name:"zh/identification/same-color-gems.md"};function i(n,t,s,o,h,p){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="同色宝石判别" tabindex="-1">同色宝石判别 <a class="header-anchor" href="#同色宝石判别" aria-label="Permalink to &quot;同色宝石判别&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>同一种颜色可能对应多种宝石——红色可能是红宝石、尖晶石、石榴石或玻璃。 结合 RI / SG / 多色性 / 包裹体，可以逐步缩小候选范围，但重叠与无法排除是正常结果。 当前提供红、蓝、绿三个最小教育性分流案例；它们用于训练“候选—证据—下一步”，不是覆盖所有材料的完整决策树。</p><aside class="gem-identification-boundary" aria-labelledby="identification-boundary-same-color-gems-zh"><p class="gem-identification-boundary__eyebrow">IDENTIFICATION BOUNDARY</p><h2 id="identification-boundary-same-color-gems-zh">边界与安全</h2><p>同色案例用于练习“候选—证据—下一步”的思路，不是按颜色和单个 RI 读数自动命名。红、蓝、绿分支都是最小教育性案例，不能覆盖所有材料、处理和仪器条件。无法排除或结果冲突时应停止过度推断并送检。 </p></aside><h2 id="鉴定步骤" tabindex="-1">鉴定步骤 <a class="header-anchor" href="#鉴定步骤" aria-label="Permalink to &quot;鉴定步骤&quot;">​</a></h2><p><strong>统一阅读协议</strong></p><p>每个颜色案例都按同一顺序处理：先固定观察条件 → 形成候选集 → 选择适用的低风险证据 → 记录支持/冲突/无法排除 → 决定是否升级。颜色只负责提出问题，不能直接给出名称。</p><h2 id="一、蓝色候选分流" tabindex="-1">一、蓝色候选分流 <a class="header-anchor" href="#一、蓝色候选分流" aria-label="Permalink to &quot;一、蓝色候选分流&quot;">​</a></h2><p><strong>1. 固定颜色与观察条件</strong></p><p>在记录“蓝色”前注明光源、背景、是否镶嵌、透明度和切磨。坦桑石的蓝紫外观会随晶体方向、切磨取向和光源变化；堇青石也可能因方向显示蓝紫、灰蓝或近无色/黄色线索。因此，先记录“在什么条件下看到什么颜色”，不要只记录一个色名。</p><p><strong>2. 用 RI 形成候选集</strong></p><table tabindex="0"><thead><tr><th>典型参考</th><th>候选方向</th><th>下一步</th></tr></thead><tbody><tr><td>1.762–1.770</td><td>刚玉族蓝宝石候选</td><td>记录双折射、多色性、样品状态和处理线索</td></tr><tr><td>1.691–1.700</td><td>坦桑石候选</td><td>结合方向性多色性、切磨和热处理背景复核</td></tr><tr><td>约 1.54–1.55</td><td>堇青石候选</td><td>用二色镜记录方向颜色，不与蓝宝石名称绑定</td></tr><tr><td>读数不稳定/无法接触</td><td>暂不分流</td><td>记录“不适用/不可靠”，不要用外观补结论</td></tr></tbody></table><p>上表是典型参考范围，不是硬阈值。样品状态、接触质量、方向和仪器条件可能使读数缺失或偏离；同一颜色下仍可能存在重叠候选。</p><p><strong>3. 用多色性提出下一步问题</strong></p><table tabindex="0"><thead><tr><th>观察</th><th>能支持什么</th><th>不能证明什么</th></tr></thead><tbody><tr><td>颜色随方向明显变化</td><td>支持具有方向性光学反应的候选</td><td>不能单独证明是坦桑石或堇青石</td></tr><tr><td>颜色变化弱或未观察到</td><td>当前条件下的观察记录</td><td>不能直接排除蓝宝石、坦桑石或堇青石</td></tr><tr><td>光源改变后颜色变化明显</td><td>提醒记录光源与颜色条件</td><td>不能直接推出处理或产地</td></tr></tbody></table><p><strong>4. 蓝色分支的升级条件</strong></p><p>出现 RI 与多色性冲突、样品镶嵌/弧面导致方向不可控、需要判断热处理或需要正式产地/天然披露时，停止继续凭颜色推断，保留原始观察并送专业实验室。</p><h2 id="二、绿色候选分流" tabindex="-1">二、绿色候选分流 <a class="header-anchor" href="#二、绿色候选分流" aria-label="Permalink to &quot;二、绿色候选分流&quot;">​</a></h2><p><strong>1. 先区分颜色观察和材料判断</strong></p><p>绿色可能来自祖母绿、沙弗莱石、橄榄石、绿色碧玺、翡翠或仿品。色调、透明度和“油润/玻璃感”只能用来建立候选集，不能作为排除依据。</p><p><strong>2. 用 RI/SG 形成候选集</strong></p><table tabindex="0"><thead><tr><th>典型参考</th><th>候选方向</th><th>下一步</th></tr></thead><tbody><tr><td>RI 1.577–1.583；SG 约 2.72</td><td>祖母绿候选</td><td>结合包裹体、处理线索和生长来源问题</td></tr><tr><td>RI 1.739–1.744；SG 约 3.61</td><td>沙弗莱石候选</td><td>与其他绿色石榴石和颜色重叠保持区分</td></tr><tr><td>RI 约 1.65–1.69；双折射明显</td><td>橄榄石候选</td><td>结合 SG、双折射、颜色和包裹体复核</td></tr><tr><td>读数不稳定/样品不可接触</td><td>暂不分流</td><td>标记限制，不能用绿色外观填补证据</td></tr></tbody></table><p>这些数值是典型参考，不是自动命名规则。绿色石榴石之间可能出现颜色重叠，橄榄石的 RI/SG 也可能随颜色与包裹体变化；任何偏离都要保留条件，而不是强行选择最接近的名称。</p><p><strong>3. 把处理与生长来源分开</strong></p><p>祖母绿的“材料身份”与“是否注油/充填”是两个问题；绿色石榴石或橄榄石的“颜色相似”也不能推出同一矿物。处理、天然/合成、产地和价值必须分别记录，不能用一个 RI 或一个外观词替代。</p><p><strong>4. 绿色分支的升级条件</strong></p><p>若需要确认注油/充填、天然与合成、翡翠与其他绿色材料的身份、复合结构或正式交易披露，应停止教育性分流并送检。若 RI、SG、光学反应和显微线索互相冲突，也应把冲突作为结果记录。</p><h2 id="三、统一结果记录模板" tabindex="-1">三、统一结果记录模板 <a class="header-anchor" href="#三、统一结果记录模板" aria-label="Permalink to &quot;三、统一结果记录模板&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>示例</th></tr></thead><tbody><tr><td>任务边界</td><td>学习筛分 / 购买前复核 / 正式披露</td></tr><tr><td>样品限制</td><td>镶嵌、弧面、尺寸、裂隙、可接触面</td></tr><tr><td>候选集</td><td>蓝宝石、坦桑石；或祖母绿、沙弗莱石、橄榄石</td></tr><tr><td>证据状态</td><td>支持候选 / 与候选一致 / 无法排除 / 不可靠</td></tr><tr><td>下一步</td><td>补充适用证据 / 保留冲突 / 送专业实验室</td></tr></tbody></table><p><strong>案例边界</strong></p><p>红、蓝、绿三条路径都只是最小教育性案例。镶嵌、弧面、表面裂隙、透明度低、无法接触或高价值样品不应强行套用；任何“支持候选”的结果都必须保留测试条件，结果冲突时优先记录冲突，而不是选择最符合直觉的名称。</p><h2 id="核心要点" tabindex="-1">核心要点 <a class="header-anchor" href="#核心要点" aria-label="Permalink to &quot;核心要点&quot;">​</a></h2><ul><li>红色案例：红宝石的 RI 与荧光结果只能共同支持候选；尖晶石、石榴石和玻璃的范围可能与其他材料重叠。</li><li>蓝色案例：蓝宝石、坦桑石和堇青石的 RI 与多色性可用于提出下一步问题，但仍不是完整鉴定决策树。</li><li>绿色案例：祖母绿、沙弗莱石和橄榄石的物性与光学线索可用于候选分流，但必须保留条件和重叠项。</li><li>荧光只能作为筛分线索：天然红宝石常见 LW 红色反应，但强弱受产地、处理与样品影响；合成品也可能出现相近反应。</li><li>任何单一观察都不能替代实验室鉴定；紫外灯、划痕和液体测试须按器材安全规范操作。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><table tabindex="0"><thead><tr><th>宝石</th><th>数值</th><th>备注</th></tr></thead><tbody><tr><td>红宝石</td><td>RI 1.76 + 红色荧光</td><td>支持刚玉/红宝石候选，仍需交叉复核</td></tr><tr><td>蓝宝石</td><td>RI 约 1.76；记录方向性多色性</td><td>与坦桑石、堇青石分流时需保留光源和方向</td></tr><tr><td>坦桑石</td><td>RI 1.691–1.700；多色性</td><td>典型参考，切磨和光源会影响外观</td></tr><tr><td>堇青石</td><td>RI 约 1.54–1.55；强多色性</td><td>需按方向记录颜色变化，不能单独命名</td></tr><tr><td>祖母绿</td><td>RI 1.577–1.583；SG 约 2.72</td><td>与处理、生长来源分开记录</td></tr><tr><td>沙弗莱石榴石</td><td>RI 1.739–1.744；SG 约 3.61</td><td>绿色重叠候选，不能仅凭颜色命名</td></tr><tr><td>橄榄石</td><td>RI 约 1.65–1.69；双折射明显</td><td>典型参考，需结合样品和包裹体条件</td></tr></tbody></table><aside class="gem-reference-block" aria-labelledby="gem-reference-title"><p class="gem-reference-block__eyebrow">SOURCE TRACE</p><h2 id="gem-reference-title">参考依据与证据边界</h2><p class="gem-reference-block__intro">本页内容用于学习与检索；来源用于说明知识依据，不代表仅凭本页即可完成具体样品鉴定。</p><ul><li><a href="https://www.gia.edu/gems-gemology/winter-2024-gemstone-analysis" target="_blank" rel="noreferrer">GIA：宝石实验室分析流程</a><span>标准宝石学测试、实验室工作流与实验室培育钻石分析示例</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/gems-gemology/winter-2019-analytical-methods-geographic-origin-determination-gemstones" target="_blank" rel="noreferrer">GIA：宝石产地分析方法综述</a><span>RI/SG 作为鉴定起点，以及产地判断所需的后续分析</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/gems-gemology/winter-2024-infrared-spectroscopy" target="_blank" rel="noreferrer">GIA：红外光谱在宝石学中的应用</a><span>光谱与原子结构、天然/合成/处理线索之间的关系</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/ruby" target="_blank" rel="noreferrer">GIA 宝石百科：红宝石</a><span>红宝石的典型 RI、双折射、比重和硬度参考</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/sapphire" target="_blank" rel="noreferrer">GIA 宝石百科：蓝宝石</a><span>蓝宝石的典型 RI、双折射、比重和硬度参考</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/emerald" target="_blank" rel="noreferrer">GIA 宝石百科：祖母绿</a><span>祖母绿的典型 RI、双折射、比重、硬度与处理/合成/仿品边界</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/spinel" target="_blank" rel="noreferrer">GIA 宝石百科：尖晶石</a><span>尖晶石的典型 RI、均质性、比重和硬度参考</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/diamond" target="_blank" rel="noreferrer">GIA 宝石百科：钻石</a><span>钻石的典型 RI、比重和硬度参考</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/zircon" target="_blank" rel="noreferrer">GIA 宝石百科：锆石</a><span>锆石的典型 RI、双折射、比重和硬度参考</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/articles/iolite-description" target="_blank" rel="noreferrer">GIA：堇青石（Iolite）描述</a><span>堇青石的强多色性与观察方向提示</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/tanzanite-description" target="_blank" rel="noreferrer">GIA：坦桑石描述</a><span>坦桑石的多色性、切磨方向、光源与热处理背景</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/peridot" target="_blank" rel="noreferrer">GIA 宝石百科：橄榄石</a><span>橄榄石典型 RI、双折射、比重和硬度参考</span><small>打开来源 ↗</small></li><li><a href="https://my.gia.edu/FAQ/gia-faq-two-green-garnet" target="_blank" rel="noreferrer">GIA FAQ：沙弗莱石与翠榴石的区别</a><span>绿色石榴石颜色重叠与矿物差异提示</span><small>打开来源 ↗</small></li></ul></aside><p><em>详见<a href="./intro.html">鉴定总览</a>。</em></p>',37)])])}const b=a(l,[["render",i]]);export{g as __pageData,b as default};
